
-- Store reusable semantic embeddings for saved memories.
-- NULL is allowed so existing memories can be backfilled safely.

ALTER TABLE memories
ADD COLUMN embedding JSONB;

-- Ensure any stored embedding is a non-empty JSON array.
ALTER TABLE memories
ADD CONSTRAINT memories_embedding_is_array
CHECK (
    embedding IS NULL
    OR (
        jsonb_typeof(embedding) = 'array'
        AND jsonb_array_length(embedding) > 0
    )
);

COMMENT ON COLUMN memories.embedding IS
'Embedding vector generated by the configured local Ollama embedding model.';
